 {img:'/images/orienteering/map.jpg',ka:'რუკა',en:'Map',dka:'წაიკითხე რელიეფი და გარემო.',den:'Read the terrain and surroundings.'},
 {img:'/images/orienteering/compass.jpg',ka:'კომპასი',en:'Compass',dka:'განსაზღვრე მიმართულება.',den:'Find your direction.'},
 {img:'/images/orienteering/controls.jpg',ka:'საკონტროლო პუნქტი',en:'Control',dka:'იპოვე საჭირო პუნქტები.',den:'Locate the required controls.'}
